import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'auth_providers.dart';class ForgotPasswordScreen extends ConsumerWidget{ForgotPasswordScreen({super.key});final phone=TextEditingController();@override Widget build(BuildContext c,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Forgot password')),body:Padding(padding:const EdgeInsets.all(24),child:Column(children:[TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone')),FilledButton(onPressed:()async{await ref.read(authRepositoryProvider).forgotPassword(phone.text);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('If the account exists, reset instructions were sent.')));},child:const Text('Send OTP'))])));}
